// Extract resume data from webhook
const body = $json;
return [{
  json: {
    resume_id: body.resume_id,
    filename: body.filename,
    file_type: body.file_type,
    file_size: body.file_size,
    job_title: body.job_title || null,
    experience_years: body.experience_years || null,
    minio_key: body.minio_key,
    status: 'processing'
  }
}];

// Step 1: OCR Extraction via the resume-api internal endpoint
// (POST /api/v1/internal/n8n/ocr) — downloads the file from MinIO and runs OCR.
// This makes the OCR node a REAL step instead of a stub.
const resumeId = $input.first().json.resume_id;
const minioKey = $input.first().json.minio_key;
const fileType = $input.first().json.file_type;
const apiKey = process.env.N8N_API_KEY || 'change-me-secret';

let ocrJson = {};
try {
  const resp = await fetch(`http://resume-api:3006/api/v1/internal/n8n/ocr`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-API-Key': apiKey },
    body: JSON.stringify({ resume_id: resumeId, minio_key: minioKey, file_type: fileType })
  });
  if (resp.ok) {
    const data = await resp.json();
    ocrJson = data.ocr_json || {};
  } else {
    console.log('OCR API returned status:', resp.status);
  }
} catch (e) {
  console.log('OCR API call failed (API may be down):', e.message);
}

// Flatten ocr_json fields (sections, raw_text, word_count, ...) onto the payload
// so the downstream ATS node can read .sections, .raw_text, .word_count directly.
return [{ json: { ...$input.first().json, ...ocrJson, ocr_status: 'completed', status: 'ocr_done' } }];

// Step 2: Deterministic ATS Scoring
const ocrJson = $input.first().json;

// ATS Scoring Logic (deterministic)
const sections = ocrJson.sections || {};
const rawText = ocrJson.raw_text || '';
const wordCount = ocrJson.word_count || 0;

// Completeness scoring
const requiredSections = {
  contact_info: ['email', 'phone', 'linkedin', 'address'],
  summary: ['summary', 'objective', 'profile'],
  experience: ['experience', 'work', 'employment'],
  education: ['education', 'degree', 'university'],
  skills: ['skills', 'technical', 'competencies']
};

let completenessScore = 0;
let sectionScores = {};
for (const [section, keywords] of Object.entries(requiredSections)) {
  const text = (sections[section] || '').toLowerCase();
  const hasSection = keywords.some(kw => text.includes(kw));
  sectionScores[section] = hasSection ? 100 : 0;
  if (hasSection) completenessScore++;
}
completenessScore = Math.round((completenessScore / Object.keys(requiredSections).length) * 100);

// Formatting scoring
let formattingScore = 100;
const bulletCount = (rawText.match(/^\s*[-•*]\s+/gm) || []).length;
if (bulletCount === 0) formattingScore -= 30;
if (wordCount < 100) formattingScore -= 20;
if (wordCount > 1000) formattingScore -= 10;
formattingScore = Math.max(0, formattingScore);

// Keyword scoring (if job_title provided)
let keywordScore = 50;
let missingKeywords = [];
const jobTitle = $input.first().json.job_title || '';
if (jobTitle) {
  const industryKeywords = {
    software: ['python', 'java', 'javascript', 'react', 'api', 'sql', 'docker', 'aws'],
    data: ['python', 'sql', 'machine learning', 'pandas', 'tensorflow', 'statistics'],
    devops: ['docker', 'kubernetes', 'terraform', 'ansible', 'aws', 'ci/cd']
  };

  let targetKeywords = [];
  for (const [industry, keywords] of Object.entries(industryKeywords)) {
    if (jobTitle.toLowerCase().includes(industry)) {
      targetKeywords = targetKeywords.concat(keywords);
    }
  }

  if (targetKeywords.length > 0) {
    const rawLower = rawText.toLowerCase();
    const matched = targetKeywords.filter(kw => rawLower.includes(kw));
    missingKeywords = targetKeywords.filter(kw => !rawLower.includes(kw));
    keywordScore = Math.round((matched.length / targetKeywords.length) * 100);
  }
}

// Quality scoring
let qualityScore = 100;
const actionVerbs = ['achieved', 'developed', 'implemented', 'improved', 'managed', 'led'];
const experience = (sections.experience || '').toLowerCase();
const verbCount = actionVerbs.filter(v => experience.includes(v)).length;
if (verbCount < 3) qualityScore -= 25;
if (!rawText.match(/\d+%/) ) qualityScore -= 15;
qualityScore = Math.max(0, qualityScore);

// Overall score
const overall = Math.round(
  keywordScore * 0.30 +
  formattingScore * 0.25 +
  completenessScore * 0.30 +
  qualityScore * 0.15
);

// Recommendations
const recommendations = [];
if (completenessScore < 60) recommendations.push('Add missing sections: contact info, summary, experience, education, skills');
if (formattingScore < 60) recommendations.push('Use bullet points and proper spacing');
if (keywordScore < 50) recommendations.push('Include more industry keywords');
if (qualityScore < 60) recommendations.push('Use more action verbs and quantify achievements');
if (wordCount < 100) recommendations.push('Expand your resume — aim for at least 100 words');

return [{
  json: {
    resume_id: $input.first().json.resume_id,
    ats_score: {
      overall: overall,
      keywords_match: keywordScore,
      formatting: formattingScore,
      completeness: completenessScore,
      section_scores: sectionScores,
      missing_keywords: missingKeywords.slice(0, 20),
      recommendations: recommendations
    },
    status: 'scored'
  }
}];

// Step 3: LLM Improvement Generation via Ollama.
// Uses the built-in global fetch (available in n8n code nodes) instead of
// axios, which is NOT bundled in n8n Code nodes by default.
const atsScore = $input.first().json.ats_score;
const ocrJson = $input.first().json;
const jobTitle = $input.first().json.job_title || 'Not specified';

// Build resume content string from parsed OCR sections.
const sections = ocrJson.sections || {};
let contentParts = [];
for (const [name, text] of Object.entries(sections)) {
  if (text) contentParts.push(`=== ${name.toUpperCase()} ===\n${text}`);
}
const resumeContent = contentParts.join('\n\n') || ocrJson.raw_text || 'No content';

// Build prompt.
const prompt = `You are an expert resume reviewer. Analyze this resume and provide improvements.

## Resume Content
${resumeContent.substring(0, 3000)}

## ATS Score
${JSON.stringify(atsScore, null, 2)}

## Job Title
${jobTitle}

Return JSON with: rewritten_sections, suggestions, keyword_suggestions, formatting_tips, estimated_ats_score_after`;

try {
  const resp = await fetch(`http://ollama:11434/api/generate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'qwen2.5:0.5b',
      prompt: prompt,
      stream: false,
      options: { temperature: 0.3, max_tokens: 2048 }
    })
  });

  let rawOutput = '';
  if (resp.ok) {
    rawOutput = (await resp.json()).response || '';
  }

  // Parse JSON from response, stripping markdown code blocks if present.
  let improvements;
  try {
    rawOutput = rawOutput.replace(/^```json\s*|\s*```$/g, '').trim();
    improvements = JSON.parse(rawOutput);
  } catch (e) {
    // Fallback if Ollama returns non-JSON.
    improvements = {
      rewritten_sections: {},
      suggestions: ['Add a professional summary', 'Use action verbs', 'Quantify achievements'],
      keyword_suggestions: [],
      formatting_tips: ['Use consistent formatting', 'Include bullet points'],
      estimated_ats_score_after: Math.min(100, atsScore.overall + 15)
    };
  }

  return [{ json: { resume_id: $input.first().json.resume_id, improvements: improvements, status: 'completed' } }];
} catch (error) {
  // Fallback if Ollama is unreachable.
  return [{ json: {
    resume_id: $input.first().json.resume_id,
    improvements: {
      rewritten_sections: {},
      suggestions: ['Add a professional summary', 'Use action verbs', 'Quantify achievements'],
      keyword_suggestions: [],
      formatting_tips: ['Use consistent formatting', 'Include bullet points'],
      estimated_ats_score_after: Math.min(100, atsScore.overall + 15)
    },
    status: 'completed',
    fallback: true
  } }];
}

// Step 4: Save results to the resume-api (which persists to PostgreSQL).
// Uses built-in fetch (axios is NOT bundled in n8n code nodes).
const resumeId = $input.first().json.resume_id;
const atsScore = $input.first().json.ats_score;
const improvements = $input.first().json.improvements;

async function callSave(action, dataObj) {
  try {
    const resp = await fetch(`http://resume-api:3006/api/v1/internal/n8n/process-resume`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-API-Key': process.env.N8N_API_KEY || 'change-me-secret' },
      body: JSON.stringify({ resume_id: resumeId, action, data: dataObj })
    });
    if (!resp.ok) {
      console.log('save API returned status:', resp.status);
    }
  } catch (e) {
    console.log(`save (${action}) failed (API may not be running):`, e.message);
  }
}

await callSave('score', atsScore);
await callSave('improve', improvements);

return [{ json: { resume_id: resumeId, status: 'pipeline_complete', ats_score: atsScore, improvements: improvements } }];
